// js/pages2.js — Kegiatan & Inventaris · Integritas · Laporan · Users · WhatsApp · CRM · Pengaturan
const tabBar = (items, aktif) => `<div class="tabs" role="tablist">${items.map(t => `<button class="tab ${t[0] === aktif ? 'on' : ''}" role="tab" data-tab="${t[0]}">${esc(t[1])}</button>`).join('')}</div>`;
const pasangTab = (root, fn) => $$('[data-tab]', root).forEach(b => b.onclick = () => fn(b.dataset.tab));

// ============================================================ KEGIATAN & INVENTARIS
Pages.kegiatan = async v => {
  const n = S.nav, role = S.me.role, input = ['admin', 'wali', 'pengurus'].includes(role), staf = ['admin', 'wali'].includes(role);
  if (!S.kelasAktif) { v.innerHTML = ph('W-08', 'Class Activities & Inventory', '') + tanpaKelas(); return; }
  const Z = { tab: 'kg', kelas: S.kelasAktif };
  v.innerHTML = ph('W-08', 'Class Activities & Inventory', 'Tugas, nilai kegiatan, dan inventaris kelas yang dapat diverifikasi.', `<span id="zk">${kelasSel('zkel', Z.kelas)}</span>${input ? '<button class="btn" id="zadd">' + ic('plus') + ' Tambah</button>' : ''}`) + `<div id="zt"></div><div id="zb">${muat()}</div>` + topo('kegiatan');
  const draw = async () => {
    $('#zt', v).innerHTML = tabBar([['kg', 'Assignments & Grades'], ['inv', 'Inventory']], Z.tab); pasangTab($('#zt', v), t => { Z.tab = t; draw(); });
    $('#zb', v).innerHTML = muat();
    try {
      if (Z.tab === 'kg') {
        const rows = await Api.d('kegiatan.list', { kelas: Z.kelas }); if (!vivo(n)) return;
        $('#zb', v).innerHTML = `<div class="card"><div class="tw"><table><thead><tr><th>Tanggal</th><th>Jenis</th><th>Judul</th><th class="num">Nilai</th><th>Dicatat</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.length ? rows.map(r => `<tr><td class="mono sm">${tgl(r.Tanggal)}</td><td>${esc(r.Jenis)}</td><td>${esc(r.Judul)}</td><td class="num b">${r.Nilai === '' ? '–' : esc(r.Nilai)}</td><td class="sm">${esc(r.pencatat)}</td><td>${sbd(r.Status)}</td><td>${staf && r.Status === 'Menunggu' && String(r.Pencatat).toLowerCase() !== S.me.email ? `<button class="btn sm" data-ok="${r.KegiatanID}">VERIF</button> <button class="btn o sm" data-no="${r.KegiatanID}">TOLAK</button>` : ''} ${staf || (input && String(r.Pencatat).toLowerCase() === S.me.email && r.Status === 'Menunggu') ? `<button class="btn danger sm" data-hk="${r.KegiatanID}">HAPUS</button>` : ''}</td></tr>`).join('') : `<tr><td colspan="7">${kosong('file', 'Belum ada kegiatan tercatat.')}</td></tr>`}</tbody></table></div></div>`;
        $$('[data-hk]', v).forEach(b => b.onclick = () => { const r = rows.find(x => x.KegiatanID === b.dataset.hk); modalHapus({ judul: 'Hapus kegiatan', ringkas: `<b>${esc(r.Judul)}</b> · ${esc(r.Jenis)} · ${tgl(r.Tanggal)}`, aksi: a => Api.call('kegiatan.hapus', { id: r.KegiatanID, alasan: a }), selesai: draw }); });
        $$('[data-ok],[data-no]', v).forEach(b => b.onclick = () => aman(b, async () => { await Api.call('kegiatan.verifikasi', { id: b.dataset.ok || b.dataset.no, keputusan: b.dataset.ok ? 'setuju' : 'tolak' }); toast('Tersimpan.'); draw(); }));
      } else {
        const rows = await Api.d('inventaris.list', { kelas: Z.kelas }); if (!vivo(n)) return;
        $('#zb', v).innerHTML = `<div class="card"><div class="tw"><table><thead><tr><th>Barang</th><th class="num">Jumlah</th><th>Kondisi</th><th>Penanggung jawab</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody>${rows.length ? rows.map(r => `<tr><td class="b">${esc(r.Nama)}</td><td class="num">${r.Jumlah}</td><td>${bd(r.Kondisi, r.Kondisi === 'Rusak' ? 'r' : r.Kondisi === 'Baik' ? 'k' : '')}</td><td>${esc(r.PenanggungJawab)}</td><td class="mono sm">${wkt(r.DiperbaruiPada)}</td><td><button class="btn o sm" data-h="${r.InvID}">RIWAYAT</button> ${input ? `<button class="btn o sm" data-e="${r.InvID}">UBAH</button> <button class="btn danger sm" data-hi="${r.InvID}">HAPUS</button>` : ''}</td></tr>`).join('') : `<tr><td colspan="6">${kosong('inv', 'Belum ada inventaris kelas.')}</td></tr>`}</tbody></table></div></div>`;
        $$('[data-h]', v).forEach(b => b.onclick = () => { const r = rows.find(x => x.InvID === b.dataset.h); modal({ title: 'Riwayat · ' + r.Nama, body: `<pre class="mono sm" style="white-space:pre-wrap;margin:0">${esc(r.Riwayat)}</pre>`, actions: [{ label: 'Tutup' }] }); });
        $$('[data-e]', v).forEach(b => b.onclick = () => formInv(rows.find(x => x.InvID === b.dataset.e)));
        $$('[data-hi]', v).forEach(b => b.onclick = () => { const r = rows.find(x => x.InvID === b.dataset.hi); modalHapus({ judul: 'Hapus inventaris', ringkas: `<b>${esc(r.Nama)}</b> · ${r.Jumlah} unit · ${esc(r.Kondisi)}`, catatan: 'Barang dihapus dari daftar inventaris kelas (riwayatnya tidak ikut). Jejak penghapusan tetap tercatat di Log Audit.', aksi: a => Api.call('inventaris.hapus', { id: r.InvID, alasan: a }), selesai: draw }); });
      }
    } catch (e) { $('#zb', v).innerHTML = `<div class="card">${kosong('alert', e.message)}</div>`; }
  };
  const formKg = () => modal({ title: 'Tambah kegiatan / tugas', body: `${fld('Jenis', `<select class="in" name="jenis">${opsi(['Tugas', 'Ulangan', 'Proyek', 'Kegiatan', 'Lainnya'])}</select>`)}${fld('Judul *', '<input class="in" name="judul" maxlength="120">')}<div class="f2">${fld('Tanggal', `<input type="date" class="in" name="tgl" value="${hariIni()}" max="${hariIni()}">`)}${fld('Nilai rata-rata (0–100)', '<input class="in" name="nilai" inputmode="numeric">', 'Opsional. Nilai tingkat kelas, bukan nilai pribadi siswa.')}</div>`, actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'p', fn: async m => { const r = await Api.call('kegiatan.simpan', { kelas: Z.kelas, jenis: val(m.el, 'jenis'), judul: val(m.el, 'judul'), tanggal: val(m.el, 'tgl'), nilai: val(m.el, 'nilai') }); toast(r.message); draw(); } }] });
  const formInv = r => modal({ title: r ? 'Ubah inventaris' : 'Tambah inventaris', body: `${fld('Nama barang *', `<input class="in" name="nama" maxlength="80" value="${esc(r ? r.Nama : '')}">`)}<div class="f2">${fld('Jumlah', `<input class="in" name="jml" inputmode="numeric" value="${r ? r.Jumlah : 1}">`)}${fld('Kondisi', `<select class="in" name="kond">${opsi(['Baik', 'Perlu Perbaikan', 'Rusak'], r ? r.Kondisi : 'Baik')}</select>`)}</div>${fld('Penanggung jawab', `<input class="in" name="pj" maxlength="60" value="${esc(r ? r.PenanggungJawab : S.me.nama)}">`)}`, actions: [{ label: 'Batal' }, { label: 'Simpan', cls: 'p', fn: async m => { const x = await Api.call('inventaris.simpan', { id: r && r.InvID, kelas: Z.kelas, nama: val(m.el, 'nama'), jumlah: val(m.el, 'jml'), kondisi: val(m.el, 'kond'), pj: val(m.el, 'pj') }); toast(x.message); draw(); } }] });
  $('#zkel', v) && ($('#zkel', v).onchange = e => { Z.kelas = S.kelasAktif = e.target.value; draw(); });
  const add = $('#zadd', v); if (add) add.onclick = () => Z.tab === 'kg' ? formKg() : formInv(null);
  draw();
};

// ============================================================ LAPORAN INTEGRITAS
const JENIS_LAP = ['Kejujuran', 'Gratifikasi', 'Kecurangan Akademik', 'Penyalahgunaan Kas', 'Lainnya'];
Pages.integritas = async v => {
  const n = S.nav, staf = ['admin', 'wali'].includes(S.me.role), L = { rows: [], sel: null, f: 'ALL' };
  v.innerHTML = ph('W-09', 'Integrity Reports', 'Laporan kejujuran dan dugaan pelanggaran — identitas pelapor dapat disembunyikan dari publik.', S.me.role !== 'pimpinan' ? `<button class="btn" id="lnew">${ic('plus')} Laporan baru</button>` : '') + `<div id="lw">${muat()}</div>` + topo('integritas');
  const draw = () => {
    const list = L.rows.filter(r => L.f === 'ALL' || r.Status === L.f), cur = L.rows.find(r => r.LaporanID === L.sel) || list[0];
    $('#lw', v).innerHTML = `<div class="chips mb">${['ALL', 'Terbuka', 'Diproses', 'Selesai'].map(f => `<button class="chip ${L.f === f ? 'on' : ''}" data-f="${f}">[${f}${f === 'ALL' ? ': ' + L.rows.length : ': ' + L.rows.filter(r => r.Status === f).length}]</button>`).join('')}</div>` +
      (L.rows.length ? `<div class="grid g46" style="align-items:start"><div class="card">${list.map(r => `<div class="it" style="padding:12px 14px;border-bottom:1px solid var(--line);cursor:pointer;${cur && cur.LaporanID === r.LaporanID ? 'background:var(--s2);box-shadow:inset 3px 0 0 var(--blk)' : ''}" data-l="${r.LaporanID}" tabindex="0" role="button"><div class="row sb2" style="align-items:flex-start"><b>${esc(r.Judul)}</b>${sbd(r.Status)}</div><div class="mono xs sub mt" style="margin-top:4px">${esc(r.LaporanID)} · ${esc(r.Jenis)} · ${tgl(r.Tanggal)}</div></div>`).join('') || kosong('shield', 'Tidak ada laporan pada filter ini.')}</div>
      <div class="card">${cur ? `<div class="ch"><h3>${esc(cur.Judul)}</h3>${sbd(cur.Status)}</div><div class="cb"><div class="mono xs sub">${esc(cur.LaporanID)} · ${esc(cur.Jenis)} · Kelas ${esc(cur.Kelas || '-')} · ${wkt(cur.DibuatPada)}</div><p style="white-space:pre-wrap">${esc(cur.Uraian)}</p><div class="lbl">Pelapor</div><div>${esc(cur.pelapor)}</div><div class="lbl mt2">Riwayat penanganan</div><pre class="mono sm" style="white-space:pre-wrap;margin:6px 0;border:1px dashed var(--line2);background:var(--s1);padding:10px">${esc(cur.Penanganan || 'Belum ada tindak lanjut.')}</pre>${staf ? `<div class="f2 mt"><div class="fld"><label>Status baru</label><select class="in" id="tst">${opsi(['Terbuka', 'Diproses', 'Selesai'], cur.Status)}</select></div><div></div></div><div class="fld"><label>Catatan tindak lanjut</label><textarea class="in" id="tcat" maxlength="400"></textarea></div><button class="btn" id="tsave">${ic('send', 14)} Simpan tindak lanjut</button>` : ''}${S.me.role === 'admin' || (cur.sendiri && cur.Status === 'Terbuka') ? `<div class="mt2"><button class="btn danger sm" id="lhapus">${ic('x', 12)} ${S.me.role === 'admin' ? 'Hapus laporan' : 'Tarik / hapus laporan saya'}</button></div>` : ''}</div>` : kosong('shield', 'Pilih laporan.')}</div></div>` : `<div class="card">${kosong('shield', 'Belum ada laporan. Terima kasih telah menjaga integritas sekolah.')}</div>`);
    $$('[data-f]', v).forEach(b => b.onclick = () => { L.f = b.dataset.f; L.sel = null; draw(); });
    $$('[data-l]', v).forEach(b => { b.onclick = () => { L.sel = b.dataset.l; draw(); }; b.onkeydown = e => { if (e.key === 'Enter') b.click(); }; });
    const lh = $('#lhapus', v); if (lh) lh.onclick = () => modalHapus({ judul: 'Hapus laporan ' + cur.LaporanID, ringkas: `<b>${esc(cur.Judul)}</b><br>${esc(cur.Jenis)} · ${tgl(cur.Tanggal)}`, catatan: 'Laporan tidak akan tampil lagi. Jejak penghapusan (siapa dan alasannya) tercatat di Log Audit.', aksi: a => Api.call('laporan.hapus', { id: cur.LaporanID, alasan: a }), selesai: () => { L.sel = null; ulang(); } });
    const ts = $('#tsave', v); if (ts) ts.onclick = e => aman(e.currentTarget, async () => { const r = await Api.call('laporan.tindak', { id: cur.LaporanID, status: $('#tst', v).value, catatan: $('#tcat', v).value }); toast(r.message); L.sel = cur.LaporanID; ulang(); });
  };
  const ulang = async () => { try { L.rows = await Api.d('laporan.list', {}); if (vivo(n)) draw(); } catch (e) { $('#lw', v).innerHTML = `<div class="card">${kosong('alert', e.message)}</div>`; } };
  const nw = $('#lnew', v); if (nw) nw.onclick = () => modal({ title: 'Laporan integritas baru', body: `${fld('Jenis laporan', `<select class="in" name="jenis">${opsi(JENIS_LAP)}</select>`)}${fld('Judul *', '<input class="in" name="judul" maxlength="120">')}${fld('Uraian kejadian *', '<textarea class="in" name="uraian" maxlength="1500" style="min-height:130px"></textarea>', 'Apa, kapan, di mana, siapa yang terlibat. Min. 20 karakter.')}<label class="chk"><input type="checkbox" name="anonim"><span>Sembunyikan nama saya dari pihak lain. Admin tetap dapat melihat identitas untuk keperluan tindak lanjut.</span></label>`, actions: [{ label: 'Batal' }, { label: 'Kirim laporan', cls: 'p', fn: async m => { const r = await Api.call('laporan.simpan', { jenis: val(m.el, 'jenis'), judul: val(m.el, 'judul'), uraian: val(m.el, 'uraian'), anonim: val(m.el, 'anonim') }); toast(r.message); ulang(); } }] });
  ulang();
};

// ============================================================ LAPORAN & EKSPOR
Pages.laporan = async v => {
  const n = S.nav, JN = [['presensi', 'Presensi'], ['kas', 'Kas Kelas'], ['barang', 'Lost & Found'], ['integritas', 'Integritas'], ['kegiatan', 'Kegiatan']];
  const R = { jenis: 'kas', dari: new Date(Date.now() + 8 * 3600e3 - 29 * 864e5).toISOString().slice(0, 10), sampai: hariIni(), kelas: '', d: null };
  v.innerHTML = ph('W-10', 'Reports & Export', 'Rekap data untuk rapat, audit, dan arsip — unduh sebagai CSV (Excel) atau cetak ke PDF.') +
    `<div class="chips mb">${JN.map(j => `<button class="chip ${R.jenis === j[0] ? 'on' : ''}" data-j="${j[0]}">[${j[1]}]</button>`).join('')}</div><div class="card"><div class="cb"><div class="grid g4" style="gap:12px"><div class="fld"><label>Dari</label><input type="date" class="in" id="rd" value="${R.dari}"></div><div class="fld"><label>Sampai</label><input type="date" class="in" id="rs" value="${R.sampai}" max="${hariIni()}"></div><div class="fld"><label>Kelas</label><select class="in" id="rk"><option value="">Semua kelas</option>${opsi(S.kelas)}</select></div><div class="fld"><label>&nbsp;</label><button class="btn" id="rgo">${ic('search', 14)} Tampilkan</button></div></div></div></div><div class="card mt" id="rp">${kosong('file', 'Pilih jenis dan rentang, lalu tekan Tampilkan.')}</div>
    <div class="bar noprint"><span class="sm mono sub" id="rinfo">—</span><div class="row"><button class="btn o" onclick="window.print()">${ic('print', 14)} Cetak / PDF</button><button class="btn" id="rcsv" disabled>${ic('download', 14)} Unduh CSV</button></div></div>` + topo('laporan');
  const go2 = async () => {
    R.dari = $('#rd', v).value; R.sampai = $('#rs', v).value; R.kelas = $('#rk', v).value; $('#rp', v).innerHTML = muat();
    try {
      const d = await Api.d('rekap.data', { jenis: R.jenis, dari: R.dari, sampai: R.sampai, kelas: R.kelas }); if (!vivo(n)) return; R.d = d;
      $('#rp', v).innerHTML = `<div class="ch"><h3>${esc(d.judul)}</h3><span class="lbl">${tgl(R.dari)} – ${tgl(R.sampai)}${R.kelas ? ' · ' + esc(R.kelas) : ''}</span></div><div class="tw"><table><thead><tr>${d.kolom.map(k => `<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${d.baris.length ? d.baris.map(b => `<tr>${b.map(c => `<td>${esc(c)}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${d.kolom.length}">${kosong('file', 'Tidak ada data pada rentang ini.')}</td></tr>`}</tbody></table></div><div class="pg"><span>${d.baris.length} baris</span><span>Dicetak ${wkt(new Date(Date.now() + 8 * 3600e3).toISOString())} oleh ${esc(S.me.nama)}</span></div>`;
      $('#rinfo', v).textContent = d.baris.length + ' baris siap diekspor'; $('#rcsv', v).disabled = !d.baris.length;
    } catch (e) { $('#rp', v).innerHTML = kosong('alert', e.message); }
  };
  $$('[data-j]', v).forEach(b => b.onclick = () => { R.jenis = b.dataset.j; $$('[data-j]', v).forEach(x => x.classList.toggle('on', x === b)); go2(); });
  $('#rgo', v).onclick = go2; $('#rcsv', v).onclick = () => unduhCsv(`${R.jenis}_${hariIni()}.csv`, R.d.kolom, R.d.baris);
  go2();
};


// ============================================================ JENDELA IMPOR (Excel .xlsx / CSV / tempel)
/** o: { judul, petunjuk, tplXlsx, tplCsv:{nama,kolom,baris}, pemeta(raw), kolom:[[key,label]], kirim(rows)→data, selesai() } */
function modalImpor(o) {
  let hasil = { rows: [], peringatan: [], kolom: [], header: true }, sibuk = false;
  const m = modal({ title: o.judul, wide: true, body: `<p class="sm" style="margin-top:0">${o.petunjuk}</p>
    <div class="row mb"><button class="btn o sm" id="itx">${ic('download', 12)} Templat Excel (.xlsx)</button><button class="btn o sm" id="itc">${ic('download', 12)} Templat CSV</button></div>
    <div class="drop" id="idrop" style="padding:18px"><div class="mono sm b">${ic('upload', 18)} [PILIH ATAU TARIK BERKAS EXCEL / CSV KE SINI]</div><div class="sm sub">.xlsx · .csv · .txt — lembar pertama dibaca</div><input type="file" id="ifile" class="hide" accept=".xlsx,.xlsm,.xls,.csv,.txt,.tsv"></div>
    ${fld('Atau tempel langsung dari Excel / Google Sheets / CSV', '<textarea class="in mono" name="csv" style="min-height:90px" placeholder="Salin sel dari Excel lalu tempel di sini. Baris judul kolom boleh ada, boleh tidak."></textarea>')}
    <div id="iprev" class="mt"></div><div id="ires" class="mono sm mt"></div>`,
    actions: [{ label: 'Tutup' }, { label: 'Impor', cls: 'p', fn: async mm => {
      if (sibuk) return false; if (!hasil.rows.length) throw new Error('Belum ada data yang terbaca. Pilih berkas atau tempel data terlebih dahulu.');
      sibuk = true; let tambah = 0, lewat = [], jml = 0;
      try { for (let i = 0; i < hasil.rows.length; i += 200) { $('#ires', mm.el).textContent = `Mengimpor ${Math.min(i + 200, hasil.rows.length)} / ${hasil.rows.length}…`; const d = await o.kirim(hasil.rows.slice(i, i + 200)); tambah += d.ditambah; jml += d.jumlahDilewati; lewat = lewat.concat(d.dilewati.map(x => x.replace(/^Baris (\d+)/, (a, n) => 'Baris ' + (Number(n) + i)))); } }
      finally { sibuk = false; }
      $('#ires', mm.el).innerHTML = `<div class="chk" style="cursor:default">${ic('shield', 16)}<span><b>✓ ${tambah} ditambahkan</b>, ${jml} dilewati (sudah terdaftar / data kurang).<br>${lewat.slice(0, 40).map(esc).join('<br>')}</span></div>`;
      toast(tambah + ' data berhasil diimpor.'); o.selesai(); hasil = { rows: [], peringatan: [], kolom: [] }; $('#iprev', mm.el).innerHTML = ''; return false;
    } }] });
  const ta = $('[name=csv]', m.el), prev = $('#iprev', m.el);
  const tampil = () => {
    if (!hasil.rows.length) { prev.innerHTML = ''; return; }
    prev.innerHTML = `<div class="row sb2 mb"><span class="lbl">PRATINJAU · ${hasil.rows.length} BARIS TERBACA</span><span class="sm sub">${hasil.header ? 'Judul kolom: ' : 'Tanpa judul kolom — dideteksi dari isi: '}${esc(hasil.kolom.join(', '))}</span></div><div class="tw" style="max-height:220px;overflow-y:auto;border:1px solid var(--line2)"><table><thead><tr><th>#</th>${o.kolom.map(c => `<th>${esc(c[1])}</th>`).join('')}</tr></thead><tbody>${hasil.rows.slice(0, 8).map((r, i) => `<tr><td class="mono sm">${i + 1}</td>${o.kolom.map(c => `<td class="sm">${esc(r[c[0]] || '')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${hasil.rows.length > 8 ? `<div class="mono xs sub">… dan ${hasil.rows.length - 8} baris lainnya</div>` : ''}${hasil.peringatan.length ? `<div class="chk mt" style="cursor:default;border-color:var(--red)">${ic('alert')}<span class="sm"><b>${hasil.peringatan.length} peringatan</b> (baris ini kemungkinan dilewati):<br>${hasil.peringatan.slice(0, 8).map(esc).join('<br>')}${hasil.peringatan.length > 8 ? '<br>…' : ''}</span></div>` : ''}`;
  };
  const proses = raw => { if (!raw.length) { hasil = { rows: [], peringatan: [], kolom: [] }; prev.innerHTML = `<div class="chk" style="cursor:default">${ic('alert')}<span class="sm">Tidak ada baris yang terbaca. Pastikan berkas berisi data pada lembar pertama.</span></div>`; return; } hasil = o.pemeta(raw); if (!hasil.rows.length) { prev.innerHTML = `<div class="chk" style="cursor:default">${ic('alert')}<span class="sm">Data terbaca, tetapi tidak ada baris yang berisi nama. Periksa kolom pertama.</span></div>`; return; } tampil(); };
  const pilih = async f => { try { $('#ires', m.el).textContent = 'Membaca ' + f.name + '…'; ta.value = ''; proses(await bacaBerkasTabel(f)); $('#ires', m.el).textContent = f.name; } catch (e) { $('#ires', m.el).textContent = ''; toast(e.message, 'err'); } };
  pasangDrop(m.el, pilih);
  ta.oninput = debounce(() => proses(bacaTabelTeks(ta.value)), 300);
  $('#itx', m.el).onclick = () => { try { unduhXlsx(o.tplXlsx.nama, o.tplXlsx.lembar); } catch (e) { toast('Templat Excel gagal dibuat: ' + e.message, 'err'); } };
  $('#itc', m.el).onclick = () => unduhCsv(o.tplCsv.nama, o.tplCsv.kolom, o.tplCsv.baris);
  return m;
}

// ============================================================ PENGGUNA
const ROLE_OPT = [['admin', 'Admin Sistem'], ['pimpinan', 'Kepala Sekolah / Manajemen'], ['wali', 'Guru / Wali Kelas'], ['pengurus', 'Pengurus Kelas'], ['siswa', 'Siswa']];
Pages.pengguna = async v => {
  const n = S.nav, U = { rows: [], q: '', role: '', st: '' };
  v.innerHTML = ph('W-11', 'Users', 'Kelola akun, peran, dan kelas. Siswa tanpa email Google hanya dicatat kehadirannya.', `<button class="btn o" id="uimp">${ic('upload')} Impor CSV</button><button class="btn" id="uadd">${ic('plus')} Tambah pengguna</button>`) + `<div class="card"><div class="cb row"><input class="in" id="uq" placeholder="Cari nama / email / kelas…" style="max-width:280px" aria-label="Cari pengguna"><select class="sel" id="ur"><option value="">Semua peran</option>${opsi(ROLE_OPT)}</select><select class="sel" id="us"><option value="">Semua status</option><option>Aktif</option><option>Nonaktif</option><option>Dihapus</option></select><span class="lbl" id="ucnt"></span></div></div><div class="card mt"><div class="tw"><table><thead><tr><th>ID</th><th>Nama</th><th>Peran</th><th>Kelas</th><th>Email Google</th><th>WhatsApp</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="ubody"><tr><td colspan="8">${muat()}</td></tr></tbody></table></div></div>`;
  const draw = () => {
    const q = U.q.toLowerCase(), list = U.rows.filter(u => (!U.role || u.Role === U.role) && (U.st ? u.Status === U.st : u.Status !== 'Dihapus') && (!q || (u.Nama + ' ' + u.Email + ' ' + u.Kelas).toLowerCase().includes(q)));
    $('#ucnt', v).textContent = list.length + ' / ' + U.rows.length + ' pengguna';
    $('#ubody', v).innerHTML = list.slice(0, 300).map(u => `<tr><td class="mono sm">${esc(u.UserID)}</td><td class="b">${esc(u.Nama)}</td><td>${bd(u.Role, u.Role === 'admin' ? 'k' : '')}</td><td class="mono sm">${esc(u.Kelas || '–')}</td><td class="sm">${esc(u.Email || '–')}</td><td class="mono sm">${esc(u.NoWA || '–')}</td><td>${bd(u.Status, u.Status === 'Aktif' ? 'k' : 'm')}</td><td>${u.Status === 'Dihapus' ? `<button class="btn o sm" data-pu="${u.UserID}">PULIHKAN</button>` : `<button class="btn o sm" data-e="${u.UserID}">UBAH</button> ${u.UserID !== S.me.userId ? `<button class="btn danger sm" data-hu="${u.UserID}">HAPUS</button>` : ''}`}</td></tr>`).join('') || `<tr><td colspan="8">${kosong('users', 'Tidak ada pengguna yang cocok.')}</td></tr>`;
    $$('[data-e]', v).forEach(b => b.onclick = () => form(U.rows.find(x => x.UserID === b.dataset.e)));
    $$('[data-hu]', v).forEach(b => b.onclick = () => hapusUser(U.rows.find(x => x.UserID === b.dataset.hu)));
    $$('[data-pu]', v).forEach(b => b.onclick = () => aman(b, async () => { const r = await Api.call('pengguna.pulihkan', { id: b.dataset.pu }); toast(r.message); ulang(); }));
  };
  const hapusUser = u => modalHapus({ judul: 'Hapus pengguna', ringkas: `<b>${esc(u.Nama)}</b> · ${esc(u.Role)}${u.Kelas ? ' · ' + esc(u.Kelas) : ''}<br>${esc(u.Email || 'tanpa email')}`, catatan: 'Akun tidak bisa masuk lagi dan hilang dari daftar kelas, presensi, dan CRM. Riwayat lama tetap tersimpan sebagai arsip. Email dan NISN-nya dapat dipakai lagi. Bisa dipulihkan lewat filter status "Dihapus".', aksi: a => Api.call('pengguna.hapus', { id: u.UserID, alasan: a }), selesai: ulang });
  const ulang = async () => { try { U.rows = await Api.d('pengguna.list', {}); if (vivo(n)) draw(); } catch (e) { $('#ubody', v).innerHTML = `<tr><td colspan="8">${kosong('alert', e.message)}</td></tr>`; } };
  const form = u => modal({ title: u ? 'Ubah pengguna · ' + u.UserID : 'Tambah pengguna', body: `${fld('Nama lengkap *', `<input class="in" name="nama" maxlength="80" value="${esc(u ? u.Nama : '')}">`)}<div class="f2">${fld('Peran *', `<select class="in" name="role">${opsi(ROLE_OPT, u ? u.Role : 'siswa')}</select>`)}${fld('Kelas', `<input class="in" name="kelas" placeholder="VIII-A (wali boleh: VIII-A,VIII-B)" value="${esc(u ? u.Kelas : '')}">`)}</div>${fld('Email Google sekolah', `<input class="in" type="email" name="email" value="${esc(u ? u.Email : '')}">`, 'Wajib untuk selain siswa. Dipakai untuk masuk dengan Google.')}<div class="f2">${fld('NISN', `<input class="in" name="nisn" inputmode="numeric" value="${esc(u ? u.NISN : '')}">`)}${fld('WhatsApp', `<input class="in" name="wa" inputmode="tel" value="${esc(u ? u.NoWA : '')}">`)}</div><div class="f2">${fld('Nama orang tua/wali', `<input class="in" name="ortu" value="${esc(u ? u.NamaOrtu : '')}">`)}${fld('WhatsApp orang tua', `<input class="in" name="waortu" inputmode="tel" value="${esc(u ? u.NoWAOrtu : '')}">`)}</div>${fld('Status', `<select class="in" name="st">${opsi(['Aktif', 'Nonaktif'], u ? u.Status : 'Aktif')}</select>`)}`, actions: [{ label: 'Batal' }, ...(u && u.UserID !== S.me.userId && u.Status !== 'Dihapus' ? [{ label: 'Hapus pengguna', cls: 'danger', fn: () => { hapusUser(u); } }] : []), { label: 'Simpan', cls: 'p', fn: async m => { const r = await Api.call('pengguna.simpan', { userId: u && u.UserID, nama: val(m.el, 'nama'), role: val(m.el, 'role'), kelas: val(m.el, 'kelas'), email: val(m.el, 'email'), nisn: val(m.el, 'nisn'), noWA: val(m.el, 'wa'), namaOrtu: val(m.el, 'ortu'), noWAOrtu: val(m.el, 'waortu'), status: val(m.el, 'st') }); toast(r.message); ulang(); } }] });
  $('#uq', v).oninput = debounce(e => { U.q = e.target.value; draw(); }, 250); $('#ur', v).onchange = e => { U.role = e.target.value; draw(); }; $('#us', v).onchange = e => { U.st = e.target.value; draw(); };
  $('#uadd', v).onclick = () => form(null);
  $('#uimp', v).onclick = () => modalImpor({
    judul: 'Impor pengguna dari Excel / CSV',
    petunjuk: 'Kolom yang dikenali: <b>nama, role, kelas, email, nisn, nowa, namaortu, nowaortu</b>. Baris judul boleh dihilangkan; sistem menebak kolom dari isinya (mis. <span class="mono">Siswa VII-B</span> dibaca sebagai peran siswa, kelas VII-B). Role: admin, pimpinan, wali, pengurus, siswa. Siswa boleh tanpa email.',
    tplXlsx: { nama: 'templat_pengguna.xlsx', lembar: [{ nama: 'Pengguna', kolom: ['nama', 'role', 'kelas', 'email', 'nisn', 'nowa', 'namaortu', 'nowaortu'], teks: [4, 5, 7], lebar: [26, 12, 16, 28, 14, 16, 18, 16], baris: [['I Putu Arya Pratama', 'siswa', 'VIII-A', '', '0091823901', '081234567890', 'Bpk. Pratama', '081234500000'], ['Ni Kadek Devi Anggraini', 'pengurus', 'VIII-A', 'kadek@sekolah.sch.id', '0091823925', '081234500002', 'Ibu Devi', '081234500003'], ['I Made Budi, S.Pd', 'wali', 'VIII-A,VIII-B', 'budi@sekolah.sch.id', '', '081234500004', '', '']] }, { nama: 'Petunjuk', kolom: [], lebar: [110], baris: [['PETUNJUK PENGISIAN (lembar ini boleh dihapus)'], [''], ['1. Isi data mulai baris 2 pada lembar "Pengguna". Baris judul boleh dihapus; sistem menebak kolom dari isinya.'], ['2. role: admin, pimpinan, wali, pengurus, atau siswa. Boleh juga ditulis "Siswa VII-B" (peran dan kelas dalam satu sel).'], ['3. kelas: contoh VIII-A. Wali yang mengampu banyak kelas: VIII-A,VIII-B.'], ['4. email: wajib untuk admin, pimpinan, wali, pengurus (akun Google). Siswa boleh kosong.'], ['5. nisn dan nomor WhatsApp: kolom sudah berformat Teks agar angka 0 di depan tidak hilang.'], ['6. nowa/nowaortu: 08xxxxxxxxxx atau 628xxxxxxxxxx.'], ['7. Data yang sudah terdaftar (email atau NISN sama) otomatis dilewati. Maksimal 5.000 baris per berkas.']] }] }, tplCsv: { nama: 'templat_pengguna.csv', kolom: ['nama', 'role', 'kelas', 'email', 'nisn', 'nowa', 'namaortu', 'nowaortu'], baris: [['I Putu Arya Pratama', 'siswa', 'VIII-A', '', '0091823901', '081234567890', 'Bpk. Pratama', '081234500000']] },
    pemeta: rowsPengguna, kolom: [['nama', 'Nama'], ['role', 'Peran'], ['kelas', 'Kelas'], ['nisn', 'NISN'], ['noWA', 'WhatsApp'], ['email', 'Email']],
    kirim: async rows => (await Api.call('pengguna.impor', { rows })).data, selesai: ulang
  });
  ulang();
};

// ============================================================ WHATSAPP & NOTIFIKASI
Pages.wa = async v => {
  const n = S.nav, W = { tab: 'blast', cfg: null, aud: [], sel: new Set(), batch: 20, auto: null };
  v.innerHTML = ph('W-12', 'WhatsApp & Notifikasi', 'Notifikasi otomatis (WA + email) lewat antrean, dan blast pesan per batch yang aman dari pemblokiran.') + `<div id="wt"></div><div id="wb">${muat()}</div>`;
  const tampil = () => {
    $('#wt', v).innerHTML = tabBar([['blast', 'Blast WhatsApp'], ['antrean', 'Antrean & Riwayat'], ['konfig', 'Konfigurasi']], W.tab); pasangTab($('#wt', v), t => { clearInterval(W.auto); W.tab = t; tampil(); });
    ({ blast: tabBlast, antrean: tabAntrean, konfig: tabKonfig })[W.tab]();
  };
  const jedaRata = j => { const p = String(j).split('-').map(Number); return p.length === 2 ? (p[0] + p[1]) / 2 : p[0]; };
  const tabBlast = async () => {
    const box = $('#wb', v); box.innerHTML = muat();
    let st, bl; try { [st, bl, W.cfg] = await Api.many([['crm.stats'], ['wa.blastList'], ['notif.config']]); } catch (e) { box.innerHTML = `<div class="card">${kosong('alert', e.message)}</div>`; return; }
    if (!vivo(n)) return; W.batch = W.cfg.batchDefault;
    const segs = Object.keys(st.segmen || {});
    box.innerHTML = `${W.cfg.waAktif ? '' : `<div class="card mb">${kosong('alert', 'WhatsApp belum aktif. Isi token Fonnte dan nyalakan saklar di tab Konfigurasi.')}</div>`}<div class="grid g2" style="align-items:start"><div class="card"><div class="ch"><h3>1. Pilih sasaran</h3></div><div class="cb"><div class="f2">${fld('Segmen', `<select class="in" id="bseg"><option value="">Semua segmen</option>${opsi(segs)}</select>`)}${fld('Kelas', `<select class="in" id="bkel"><option value="">Semua kelas</option>${opsi(S.kelas)}</select>`)}</div><div class="row mb"><button class="btn o" id="bmuat">${ic('users', 14)} Muat penerima</button><button class="btn o" id="bdet">${ic('search', 14)} Deteksi nomor WA</button></div><div id="bsum" class="chips mb"></div><label class="chk"><input type="checkbox" id="bhanya"><span>Kirim hanya ke nomor yang terdeteksi WhatsApp</span></label><div class="tw" style="max-height:320px;overflow-y:auto;border:1px solid var(--line2)"><table><thead><tr><th><input type="checkbox" id="ball" aria-label="Pilih semua"></th><th>Nama</th><th>Nomor</th><th>WA</th></tr></thead><tbody id="bbody"><tr><td colspan="4" class="mut c">Tekan “Muat penerima”.</td></tr></tbody></table></div></div></div>
    <div><div class="card"><div class="ch"><h3>2. Tulis pesan</h3></div><div class="cb">${fld('Judul internal', '<input class="in" id="bjud" maxlength="80" placeholder="Pengumuman rapat wali murid">')}<div class="row mb gap8"><span class="lbl">Sisipkan:</span><button class="btn o sm" data-var="{nama}">{nama}</button><button class="btn o sm" data-var="{institusi}">{institusi}</button></div>${fld('Isi pesan *', '<textarea class="in" id="bpesan" maxlength="1000" style="min-height:120px" placeholder="Yth. {nama}, ..."></textarea>')}<div class="lbl">Pratinjau</div><div class="bubble mt" id="bprev" style="margin-top:6px">…</div></div></div>
    <div class="card mt"><div class="ch"><h3>3. Ukuran batch &amp; jeda</h3></div><div class="cb"><div class="row mb"><div class="seg" id="bseg2">${[10, 20, 50].map(b => `<button data-b="${b}" class="${b === W.batch ? 'on' : ''}">${b}</button>`).join('')}</div><div class="fld" style="margin:0"><input class="in" id="bjeda" value="${esc(W.cfg.jeda)}" style="width:90px" aria-label="Jeda detik"></div><span class="sm sub">detik antarpesan (contoh 5 atau 3-8)</span></div><div class="sm sub" id="bring">Pilih penerima untuk melihat estimasi.</div><button class="btn mt" id="bstart" disabled>${ic('send', 14)} Mulai blast</button><p class="sm sub">Tips anti-blokir: mulai dari batch 10, jeda acak ≥5 detik, jangan kirim tautan yang sama ke ratusan orang dalam satu jam.</p></div></div></div></div>
    <div class="card mt"><div class="ch"><h3>Riwayat blast</h3></div><div class="tw"><table><thead><tr><th>Judul</th><th>Sasaran</th><th>Batch · jeda</th><th>Progres</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${bl.length ? bl.map(b => `<tr><td class="b">${esc(b.Judul)}<div class="mono xs sub">${esc(b.BlastID)} · ${wkt(b.Tanggal)}</div></td><td>${esc(b.Sasaran || '-')}</td><td class="mono sm">${b.UkuranBatch} · ${esc(b.JedaDetik)} dtk</td><td style="min-width:150px"><div class="prog"><i style="width:${b.persen}%"></i></div><div class="mono xs mt" style="margin-top:3px">✓ ${b.Terkirim} · ✕ ${b.Gagal} · sisa ${b.sisa} / ${b.Total}</div></td><td>${sbd(b.Status)}</td><td>${b.Status === 'Berjalan' ? `<button class="btn sm" data-p="${b.BlastID}">KIRIM BATCH</button> <button class="btn danger sm" data-s="${b.BlastID}">STOP</button>` : ''}</td></tr>`).join('') : `<tr><td colspan="6">${kosong('send', 'Belum ada blast.')}</td></tr>`}</tbody></table></div><div class="cf">Server tetap mengirim 1 batch per menit lewat trigger walau halaman ditutup.</div></div>`;
    const sum = () => { const rows = W.aud, ok = rows.filter(r => r.valid && !r.ganda && !r.optOut && (!$('#bhanya', v).checked || r.statusWA === 'Terdaftar')), pil = [...W.sel].filter(id => ok.some(r => r.id === id)); W.pil = ok.filter(r => W.sel.has(r.id));
      $('#bsum', v).innerHTML = rows.length ? [['TOTAL', rows.length], ['VALID', rows.filter(r => r.valid).length], ['TIDAK VALID', rows.filter(r => !r.valid).length], ['GANDA', rows.filter(r => r.ganda).length], ['OPT-OUT', rows.filter(r => r.optOut).length]].map(x => `<span class="bd">[${x[0]}: ${x[1]}]</span>`).join('') : '';
      const jm = jedaRata($('#bjeda', v).value) || 5, mnt = Math.ceil(W.pil.length / W.batch), est = Math.round(W.pil.length * jm / 60);
      $('#bring', v).textContent = W.pil.length ? `${W.pil.length} penerima → ${mnt} batch · ± ${est} menit` : 'Pilih penerima untuk melihat estimasi.'; $('#bstart', v).disabled = !W.pil.length || !W.cfg.waAktif || $('#bpesan', v).value.trim().length < 5;
      const nm = (W.aud[0] || { nama: 'Bapak/Ibu' }).nama; $('#bprev', v).textContent = ($('#bpesan', v).value || '…').replace(/\{nama\}/g, nm).replace(/\{institusi\}/g, S.cfg.NAMA_SEKOLAH || ''); };
    const gambar = () => { $('#bbody', v).innerHTML = W.aud.length ? W.aud.slice(0, 600).map(r => { const bisa = r.valid && !r.ganda && !r.optOut, redup = bisa ? '' : 'opacity:.45'; return `<tr style="${redup}"><td><input type="checkbox" data-i="${r.id}" ${W.sel.has(r.id) ? 'checked' : ''} ${bisa ? '' : 'disabled'} aria-label="Pilih ${esc(r.nama)}"></td><td>${esc(r.nama)}<div class="mono xs sub">${esc(r.segmen)}</div></td><td class="mono sm">${esc(r.hp)}</td><td>${r.statusWA === 'Terdaftar' ? bd('✓ WA', 'k') : r.statusWA === 'Tidak Terdaftar' ? bd('✕ BUKAN WA', 'r') : bd('? BELUM', 'm')}${r.optOut ? bd('OPT-OUT', 'r') : ''}${r.ganda ? bd('GANDA', 'm') : ''}</td></tr>`; }).join('') : '<tr><td colspan="4" class="mut c">Tidak ada penerima.</td></tr>';
      $$('[data-i]', v).forEach(c => c.onchange = () => { c.checked ? W.sel.add(c.dataset.i) : W.sel.delete(c.dataset.i); sum(); }); sum(); };
    const muatAud = async () => { const d = await Api.d('wa.audience', { segmen: $('#bseg', v).value, kelas: $('#bkel', v).value }); W.aud = d.rows; W.sel = new Set(d.rows.filter(r => r.valid && !r.ganda && !r.optOut).map(r => r.id)); gambar(); };
    $('#bmuat', v).onclick = e => aman(e.currentTarget, muatAud);
    $('#ball', v).onchange = e => { W.sel = e.target.checked ? new Set(W.aud.filter(r => r.valid && !r.ganda && !r.optOut).map(r => r.id)) : new Set(); gambar(); };
    $('#bhanya', v).onchange = sum; $('#bpesan', v).oninput = sum; $('#bjeda', v).oninput = sum;
    $$('[data-var]', v).forEach(b => b.onclick = () => { const t = $('#bpesan', v); t.value += b.dataset.var; sum(); });
    $$('#bseg2 button', v).forEach(b => b.onclick = () => { W.batch = Number(b.dataset.b); $$('#bseg2 button', v).forEach(x => x.classList.toggle('on', x === b)); sum(); });
    $('#bdet', v).onclick = e => aman(e.currentTarget, async () => {
      if (!W.aud.length) await muatAud(); const hp = [...new Set(W.aud.filter(r => r.valid).map(r => r.hp))]; let sudah = 0;
      for (let i = 0; i < hp.length; i += 50) { const r = await Api.call('wa.validate', { nomor: hp.slice(i, i + 50) }); sudah += hp.slice(i, i + 50).length; toast(`Mengecek ${Math.min(sudah, hp.length)}/${hp.length}…`); Object.keys(r.data.map).forEach(k => W.aud.forEach(a => { if (a.hp === k) a.statusWA = r.data.map[k]; })); }
      gambar(); toast('Deteksi nomor selesai.');
    });
    $('#bstart', v).onclick = async e => {
      if (!await tanya(`Mulai blast ke ${W.pil.length} nomor dalam batch ${W.batch}? Pesan tidak dapat ditarik setelah terkirim.`, 'Mulai blast')) return;
      aman(e.currentTarget, async () => { const r = await Api.call('wa.blastCreate', { judul: $('#bjud', v).value, pesan: $('#bpesan', v).value, ukuranBatch: W.batch, jeda: $('#bjeda', v).value, sasaran: $('#bseg', v).value || 'Semua', penerima: W.pil.map(x => ({ hp: x.hp, nama: x.nama })) }); toast(r.message); tabBlast(); });
    };
    $$('[data-p]', v).forEach(b => b.onclick = () => aman(b, async () => { await Api.call('wa.blastProcess', { blastId: b.dataset.p }); toast('Batch diproses.'); tabBlast(); }));
    $$('[data-s]', v).forEach(b => b.onclick = async () => { if (await tanya('Hentikan blast ini? Pesan yang belum terkirim dibatalkan.', 'Hentikan')) aman(b, async () => { const r = await Api.call('wa.blastStop', { blastId: b.dataset.s }); toast(r.message); tabBlast(); }); });
  };
  const tabAntrean = async () => {
    const box = $('#wb', v); box.innerHTML = muat(); const F = { status: '', kanal: '' };
    const muatQ = async () => {
      try { const d = await Api.d('notif.queue', F); if (!vivo(n)) return; const r = d.ringkas;
        box.innerHTML = `<div class="grid g4">${[['MENUNGGU', r.Antri], ['TERKIRIM', r.Terkirim], ['GAGAL', r.Gagal], ['DIBATALKAN', r.Batal]].map(x => `<div class="card k kpi" style="min-height:0"><span class="lbl">${x[0]}</span><div class="v">${x[1]}</div></div>`).join('')}</div><div class="card mt"><div class="cb row sb2"><div class="row"><select class="sel" id="qs"><option value="">Semua status</option>${opsi(['Antri', 'Terkirim', 'Gagal', 'Batal'], F.status)}</select><select class="sel" id="qk"><option value="">Semua kanal</option>${opsi(['WA', 'EMAIL'], F.kanal)}</select></div><div class="row"><button class="btn o" id="qproc">${ic('send', 14)} Proses sekarang</button><button class="btn o" id="qretry">Ulangi yang gagal</button></div></div></div><div class="card mt"><div class="tw"><table><thead><tr><th>Waktu</th><th>Kanal</th><th>Tujuan</th><th>Event</th><th>Pesan</th><th>Status</th></tr></thead><tbody>${d.rows.length ? d.rows.map(x => `<tr><td class="mono sm">${wkt(x.Waktu)}</td><td>${bd(x.Kanal, x.Kanal === 'WA' ? 'k' : '')}</td><td class="mono sm">${esc(x.Tujuan)}<div class="xs sub">${esc(x.Nama)}</div></td><td class="mono xs">${esc(x.Event)}</td><td class="sm">${esc(x.Pesan)}</td><td>${sbd(x.Status)}${x.Status === 'Gagal' ? `<div class="xs red">${esc(x.Respon)}</div>` : ''}</td></tr>`).join('') : `<tr><td colspan="6">${kosong('send', 'Antrean kosong.')}</td></tr>`}</tbody></table></div></div>`;
        $('#qs', v).onchange = e => { F.status = e.target.value; muatQ(); }; $('#qk', v).onchange = e => { F.kanal = e.target.value; muatQ(); };
        $('#qproc', v).onclick = e => aman(e.currentTarget, async () => { const r = await Api.d('notif.processNow', {}); toast('Diproses: ' + (r.terkirim || 0) + ' terkirim.'); muatQ(); });
        $('#qretry', v).onclick = e => aman(e.currentTarget, async () => { const r = await Api.call('notif.retry', {}); toast(r.message); muatQ(); });
      } catch (e) { box.innerHTML = `<div class="card">${kosong('alert', e.message)}</div>`; }
    }; muatQ();
  };
  const tabKonfig = async () => {
    const box = $('#wb', v); box.innerHTML = muat(); let c; try { c = await Api.d('notif.config', {}); } catch (e) { box.innerHTML = `<div class="card">${kosong('alert', e.message)}</div>`; return; } if (!vivo(n)) return;
    const mx = {}; c.matriks.forEach(m => mx[m.kode] = { wa: m.wa, email: m.email, subjek: m.subjek, pesan: m.pesan });
    box.innerHTML = `<div class="grid g2" style="align-items:start"><div class="card"><div class="ch"><h3>${ic('send', 16)} WhatsApp (Fonnte)</h3><span class="sw ${c.waAktif ? 'on' : ''}" id="swwa" role="switch" aria-checked="${c.waAktif}" tabindex="0" aria-label="Saklar WhatsApp"></span></div><div class="cb">${fld('Token Fonnte', `<input class="in mono" type="password" autocomplete="off" id="ctok" placeholder="${c.tokenAda ? esc(c.token) : 'Tempel token dari fonnte.com'}">`, 'Disimpan di Script Properties server. Kosongkan bila tidak diubah; ketik __HAPUS__ untuk menghapus.')}<div class="f2">${fld('Batch bawaan', `<select class="in" id="cbat">${opsi([10, 20, 50], c.batchDefault)}</select>`)}${fld('Jeda (detik)', `<input class="in" id="cjeda" value="${esc(c.jeda)}">`)}</div><label class="chk"><input type="checkbox" id="cdet" ${c.deteksi ? 'checked' : ''}><span>Deteksi otomatis nomor kontak baru terdaftar WhatsApp</span></label><div class="row"><button class="btn o" id="cdev">${ic('shield', 14)} Cek perangkat</button><input class="in" id="cno" placeholder="08xxxxxxxxxx" style="max-width:160px" aria-label="Nomor tes"><button class="btn o" id="cwa">Kirim tes WA</button></div><div class="mono sm mt" id="cinfo"></div></div></div>
    <div class="card"><div class="ch"><h3>${ic('file', 16)} Email</h3><span class="sw ${c.emailAktif ? 'on' : ''}" id="swem" role="switch" aria-checked="${c.emailAktif}" tabindex="0" aria-label="Saklar email"></span></div><div class="cb">${fld('Nama pengirim', `<input class="in" id="cnama" maxlength="60" value="${esc(c.namaPengirim)}">`)}${fld('URL aplikasi (untuk {link})', `<input class="in" id="curl" placeholder="https://username.github.io/siakas/" value="${esc(c.appUrl)}">`)}<div class="sm sub">Sisa kuota email hari ini: <b>${c.kuotaEmail}</b> · Trigger antrean: ${c.trigger ? bd('AKTIF', 'k') : bd('MATI', 'r')}</div><div class="row mt"><input class="in" id="cem" type="email" placeholder="email@tujuan" style="max-width:220px" aria-label="Email tes"><button class="btn o" id="cemt">Kirim tes email</button></div></div></div></div>
    <div class="card mt"><div class="ch"><h3>Matriks notifikasi otomatis</h3><span class="lbl">peristiwa × kanal</span></div><div class="tw"><table><thead><tr><th>Peristiwa</th><th class="c">WA</th><th class="c">Email</th><th>Pesan</th></tr></thead><tbody>${c.matriks.map(m => `<tr><td><b>${esc(m.label)}</b><div class="mono xs sub">${esc(m.kode)}</div></td><td class="c"><span class="sw ${m.wa ? 'on' : ''}" data-m="${m.kode}" data-k="wa" role="switch" tabindex="0" aria-label="WA ${esc(m.kode)}"></span></td><td class="c"><span class="sw ${m.email ? 'on' : ''}" data-m="${m.kode}" data-k="email" role="switch" tabindex="0" aria-label="Email ${esc(m.kode)}"></span></td><td><button class="btn o sm" data-ed="${m.kode}">UBAH PESAN</button></td></tr>`).join('')}</tbody></table></div><div class="cf">Variabel: {nama} {institusi} {link} + variabel khusus tiap peristiwa (mis. {kelas}, {jumlah}, {kode}).</div></div>
    <div class="bar"><span class="sm mono sub">Pesan transaksional tetap dikirim kepada kontak opt-out; hanya blast yang menghormati opt-out.</span><button class="btn" id="csave">${ic('download', 14)} Simpan konfigurasi</button></div>`;
    const sw = (el, fn) => { el.onclick = () => { el.classList.toggle('on'); el.setAttribute('aria-checked', el.classList.contains('on')); fn && fn(el.classList.contains('on')); }; el.onkeydown = e => { if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); el.click(); } }; };
    sw($('#swwa', v)); sw($('#swem', v)); $$('[data-m]', v).forEach(s => sw(s, on => { mx[s.dataset.m][s.dataset.k] = on; }));
    $$('[data-ed]', v).forEach(b => b.onclick = () => { const k = b.dataset.ed, m = c.matriks.find(x => x.kode === k); modal({ title: 'Ubah pesan · ' + k, wide: true, body: `${fld('Subjek email', `<input class="in" name="sub" maxlength="120" value="${esc(mx[k].subjek)}">`)}${fld('Isi pesan', `<textarea class="in" name="msg" style="min-height:150px" maxlength="900">${esc(mx[k].pesan)}</textarea>`, 'Gunakan *tebal* untuk huruf tebal di WhatsApp.')}`, actions: [{ label: 'Kembalikan bawaan', fn: () => { mx[k].subjek = m.subjekDefault; mx[k].pesan = m.pesanDefault; toast('Dikembalikan ke bawaan (belum disimpan).'); } }, { label: 'Pakai', cls: 'p', fn: m2 => { mx[k].subjek = val(m2.el, 'sub'); mx[k].pesan = val(m2.el, 'msg'); } }] }); });
    $('#csave', v).onclick = e => aman(e.currentTarget, async () => { const r = await Api.call('notif.configSave', { waAktif: $('#swwa', v).classList.contains('on'), emailAktif: $('#swem', v).classList.contains('on'), token: $('#ctok', v).value, batchDefault: Number($('#cbat', v).value), jeda: $('#cjeda', v).value, deteksi: $('#cdet', v).checked, namaPengirim: $('#cnama', v).value, appUrl: $('#curl', v).value, matriks: mx }); toast('Konfigurasi notifikasi disimpan.'); tabKonfig(); });
    $('#cdev', v).onclick = e => aman(e.currentTarget, async () => { const d = await Api.d('wa.device', {}); $('#cinfo', v).textContent = `Nomor ${d.nomor} · ${d.status} · paket ${d.paket} · kuota ${d.kuota} · berakhir ${d.berakhir}`; });
    $('#cwa', v).onclick = e => aman(e.currentTarget, async () => { const r = await Api.call('wa.test', { nomor: $('#cno', v).value }); toast(r.message); });
    $('#cemt', v).onclick = e => aman(e.currentTarget, async () => { const r = await Api.call('email.test', { email: $('#cem', v).value }); toast(r.message); });
  };
  v.addEventListener('DOMNodeRemoved', () => clearInterval(W.auto));
  tampil();
};

// ============================================================ CRM KONTAK
Pages.crm = async v => {
  const n = S.nav, C = { q: '', segmen: '', statusWA: '', optOut: false, duplikat: false, hal: 1, sel: new Set(), rows: [] };
  v.innerHTML = ph('W-13', 'CRM Kontak', 'Satu layar untuk memantau Nama · Email · WhatsApp seluruh siswa, orang tua, dan guru — kualitas data, status WA, dan riwayat dihubungi.', `<button class="btn o" id="cimp">${ic('upload')} Impor CSV</button><button class="btn" id="csync">${ic('clock')} Sinkron sekarang</button>`) + `<div id="ck"></div><div class="card mt"><div class="cb"><div class="row sb2"><div class="row"><input class="in" id="cq" placeholder="Cari nama / email / nomor…" style="width:260px" aria-label="Cari kontak"><select class="sel" id="cw"><option value="">Status WA: semua</option><option value="Terdaftar">Terdaftar WA</option><option value="Tidak Terdaftar">Bukan WA</option><option value="Belum">Belum dicek</option></select></div><div class="row noprint" id="cbulk"></div></div><div class="chips mt" id="cseg" style="margin-top:10px"></div></div></div><div class="card mt"><div class="tw"><table><thead><tr><th><input type="checkbox" id="call" aria-label="Pilih halaman ini"></th><th>Nama</th><th>Email</th><th>WhatsApp</th><th>Tag</th><th>Terakhir dihubungi</th><th class="num">Pesan</th><th></th></tr></thead><tbody id="cbody"><tr><td colspan="8">${muat()}</td></tr></tbody></table></div><div class="pg" id="cpg"></div></div>`;
  const kpi = async () => { try { const s = await Api.d('crm.stats', {}); if (!vivo(n)) return;
    const K = [['TOTAL KONTAK', s.total, ''], ['WA VALID', s.punyaWA, ''], ['TERDAFTAR WA', s.terdaftar, 'statusWA:Terdaftar'], ['EMAIL VALID', s.emailValid, ''], ['BELUM DICEK WA', s.belumDicek, 'statusWA:Belum'], ['OPT-OUT', s.optOut, 'optOut'], ['DUPLIKAT', s.duplikat, 'duplikat']];
    $('#ck', v).innerHTML = `<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${K.map(k => `<button class="card k kpi" style="min-height:0;text-align:left;cursor:${k[2] ? 'pointer' : 'default'};background:#fff" data-kf="${k[2]}"><span class="lbl">${k[0]}</span><div class="v">${k[1]}</div></button>`).join('')}</div><div class="sm sub mono mt" style="margin-top:6px">Sinkron terakhir: ${s.sinkronTerakhir ? wkt(new Date(s.sinkronTerakhir + 8 * 3600e3).toISOString()) : 'belum pernah — tekan “Sinkron sekarang”'} · tidak bisa dihubungi: ${s.tidakBisa} · baru 7 hari: ${s.baru7}</div>`;
    $$('[data-kf]', v).forEach(b => b.onclick = () => { const f = b.dataset.kf; if (!f) return; C.statusWA = ''; C.optOut = false; C.duplikat = false; if (f.startsWith('statusWA:')) C.statusWA = f.split(':')[1]; else C[f] = true; $('#cw', v).value = C.statusWA; C.hal = 1; muatC(); });
  } catch (e) { toast(e.message, 'err'); } };
  const muatC = async () => {
    try { const d = await Api.d('crm.list', { cari: C.q, segmen: C.segmen, statusWA: C.statusWA, optOut: C.optOut, duplikat: C.duplikat, halaman: C.hal }); if (!vivo(n)) return; C.rows = d.rows; C.d = d;
      $('#cseg', v).innerHTML = [['', 'Semua'], ...Object.keys(d.facet).map(k => [k, k + ' ' + d.facet[k]])].map(x => `<button class="chip ${C.segmen === x[0] ? 'on' : ''}" data-sg="${esc(x[0])}">[${esc(x[1])}]</button>`).join('');
      $$('[data-sg]', v).forEach(b => b.onclick = () => { C.segmen = b.dataset.sg; C.hal = 1; muatC(); });
      $('#cbody', v).innerHTML = d.rows.length ? d.rows.map(k => `<tr style="${k.dup || !hpOk(k.NoWA) ? 'background:#fffbe6' : ''}"><td><input type="checkbox" data-s="${k.KontakID}" ${C.sel.has(k.KontakID) ? 'checked' : ''} aria-label="Pilih ${esc(k.Nama)}"></td><td><b>${esc(k.Nama)}</b><div>${bd(k.Segmen)}${k.OptOut === 'YA' ? bd('OPT-OUT', 'r') : ''}${k.dup ? bd('DUPLIKAT', 'm') : ''}</div></td><td class="sm">${k.Email ? esc(k.Email) + (k.EmailValid === 'TIDAK' ? ' ⚠' : '') : '<span class="mut">–</span>'}</td><td class="mono sm">${k.NoWA ? `<a href="https://wa.me/${k.NoWA.replace(/^0/, '62')}" target="_blank" rel="noopener">${esc(k.NoWA)}</a> ${k.StatusWA === 'Terdaftar' ? bd('✓ WA', 'k') : k.StatusWA === 'Tidak Terdaftar' ? bd('✕', 'r') : bd('?', 'm')}` : '<span class="mut">–</span>'}</td><td class="sm">${esc(k.Tag || '')}</td><td class="mono sm">${k.TerakhirDihubungi ? wkt(k.TerakhirDihubungi) : '–'}</td><td class="num">${k.JumlahPesan || 0}</td><td><button class="btn o sm" data-dt="${k.KontakID}">DETAIL</button>${k.Sumber === 'manual' ? ` <button class="btn danger sm" data-dk="${k.KontakID}">HAPUS</button>` : ''}</td></tr>`).join('') : `<tr><td colspan="8">${kosong('users', d.total ? '' : 'Belum ada kontak. Tekan “Sinkron sekarang” untuk menarik dari data pengguna.')}</td></tr>`;
      const hm = Math.max(1, Math.ceil(d.total / d.per)); $('#cpg', v).innerHTML = `<span>${d.total} kontak</span><span class="row gap8"><button class="btn o sm" data-pg="${d.halaman - 1}" ${d.halaman <= 1 ? 'disabled' : ''}>&lt; PREV</button><b>${d.halaman} / ${hm}</b><button class="btn o sm" data-pg="${d.halaman + 1}" ${d.halaman >= hm ? 'disabled' : ''}>NEXT &gt;</button></span>`;
      $$('[data-pg]', v).forEach(b => b.onclick = () => { C.hal = Number(b.dataset.pg); muatC(); });
      $$('[data-s]', v).forEach(c => c.onchange = () => { c.checked ? C.sel.add(c.dataset.s) : C.sel.delete(c.dataset.s); bulk(); });
      $$('[data-dt]', v).forEach(b => b.onclick = () => detail(b.dataset.dt));
      $$('[data-dk]', v).forEach(b => b.onclick = () => { const k = C.rows.find(x => x.KontakID === b.dataset.dk); hapusKontak([k.KontakID], `<b>${esc(k.Nama)}</b> · ${esc(k.Email || k.NoWA || '')}`); }); bulk();
    } catch (e) { $('#cbody', v).innerHTML = `<tr><td colspan="8">${kosong('alert', e.message)}</td></tr>`; }
  };
  const hpOk = h => /^08\d{8,12}$/.test(h || '');
  const bulk = () => { const k = C.sel.size; $('#cbulk', v).innerHTML = k ? `<span class="lbl">${k} dipilih</span><button class="btn o sm" data-ba="tag">🏷 Beri tag</button><button class="btn o sm" data-ba="optout">⛔ Opt-out</button><button class="btn o sm" data-ba="optin">Opt-in</button><button class="btn danger sm" data-ba="hapus">Hapus</button>` : ''; $$('[data-ba]', v).forEach(b => b.onclick = () => aksiMassal(b.dataset.ba)); };
  const hapusKontak = (ids, ringkas) => modalHapus({ judul: 'Hapus kontak', ringkas, catatan: 'Kontak tidak muncul lagi di daftar dan blast. Hanya kontak manual (hasil impor) yang bisa dihapus di sini; kontak siswa/orang tua/guru dihapus lewat menu Users.', aksi: a => Api.call('crm.hapus', { ids, alasan: a }), selesai: () => { ids.forEach(i => C.sel.delete(i)); muatC(); kpi(); } });
  const aksiMassal = a => { if (a === 'hapus') return hapusKontak([...C.sel], `${C.sel.size} kontak terpilih`); const jalan = async nilai => { const r = await Api.call('crm.bulk', { ids: [...C.sel], aksi: a, nilai }); toast(r.message); C.sel.clear(); muatC(); kpi(); }; if (a === 'tag') modal({ title: 'Beri tag', body: fld('Nama tag', '<input class="in" name="tg" maxlength="24">'), actions: [{ label: 'Batal' }, { label: 'Terapkan', cls: 'p', fn: m => jalan(val(m.el, 'tg')) }] }); else jalan(''); };
  const detail = async id => {
    try { const d = await Api.d('crm.detail', { id }), k = d.kontak, tl = [...d.interaksi.map(i => ({ w: i.Tanggal, t: i.Kanal + ': ' + i.Ringkasan })), ...d.pesan.map(p => ({ w: p.waktu, t: p.kanal + ' (' + p.status + '): ' + p.ringkasan }))].sort((a, b) => String(b.w).localeCompare(String(a.w))).slice(0, 25);
      const m = modal({ title: k.Nama, wide: true, body: `<div class="grid g2"><div><div class="mono sm">${esc(k.KontakID)} · ${esc(k.Segmen)} · sumber ${esc(k.Sumber)}</div><div class="mt sm">Info: ${Object.keys(d.info).map(x => esc(x) + ': ' + esc(d.info[x])).join(' · ') || '–'}</div>${k.Sumber === 'manual' ? `<div class="mt">${fld('Nama', `<input class="in" name="nm" value="${esc(k.Nama)}">`)}${fld('Email', `<input class="in" name="em" value="${esc(k.Email)}">`)}${fld('WhatsApp', `<input class="in" name="wa" value="${esc(k.NoWA)}">`)}</div>` : `<div class="sm mt">Email: ${esc(k.Email || '–')}<br>WA: ${esc(k.NoWA || '–')}<br><span class="sub">Identitas diubah di menu Users.</span></div>`}<div class="mt">${fld('Tag (pisah koma)', `<input class="in" name="tag" value="${esc(k.Tag)}">`)}${fld('Catatan', `<textarea class="in" name="cat">${esc(k.Catatan)}</textarea>`)}<label class="chk"><input type="checkbox" name="opt" ${k.OptOut === 'YA' ? 'checked' : ''}><span>Opt-out (tidak menerima blast)</span></label></div></div><div><div class="lbl">Catat interaksi</div><div class="row mb"><select class="sel" id="ik">${opsi(['Telepon', 'WA Manual', 'Kunjungan', 'Catatan'])}</select><input class="in" id="ir" placeholder="Ringkasan…" style="flex:1;min-width:140px"><button class="btn o sm" id="iadd">TAMBAH</button></div><div class="lbl">Timeline</div>${tl.map(t => `<div class="chk" style="cursor:default"><span><span class="mono xs sub">${wkt(t.w)}</span><br>${esc(t.t)}</span></div>`).join('') || '<div class="sub sm">Belum ada riwayat.</div>'}</div></div>`, actions: [{ label: 'Tutup' }, ...(k.Sumber === 'manual' ? [{ label: 'Hapus kontak', cls: 'danger', fn: () => { hapusKontak([id], `<b>${esc(k.Nama)}</b>`); } }] : []), { label: 'Simpan', cls: 'p', fn: async mm => { await Api.call('crm.save', { id, tag: val(mm.el, 'tag'), catatan: val(mm.el, 'cat'), optOut: val(mm.el, 'opt'), nama: val(mm.el, 'nm'), email: val(mm.el, 'em'), noWA: val(mm.el, 'wa') }); toast('Kontak disimpan.'); muatC(); kpi(); } }] });
      $('#iadd', m.el).onclick = e => aman(e.currentTarget, async () => { await Api.call('crm.interaksi', { kontakId: id, kanal: $('#ik', m.el).value, ringkasan: $('#ir', m.el).value }); toast('Interaksi dicatat.'); m.close(); detail(id); });
    } catch (e) { toast(e.message, 'err'); }
  };
  $('#cq', v).oninput = debounce(e => { C.q = e.target.value; C.hal = 1; muatC(); }); $('#cw', v).onchange = e => { C.statusWA = e.target.value; C.hal = 1; muatC(); };
  $('#call', v).onchange = e => { C.rows.forEach(k => e.target.checked ? C.sel.add(k.KontakID) : C.sel.delete(k.KontakID)); muatC(); };
  $('#csync', v).onclick = e => aman(e.currentTarget, async () => { const r = await Api.call('crm.sync', {}); toast(r.message); muatC(); kpi(); });
  $('#cimp', v).onclick = () => modalImpor({
    judul: 'Impor kontak luar dari Excel / CSV',
    petunjuk: 'Untuk calon peserta, tamu undangan, atau mitra yang belum ada di data pengguna. Kolom: <b>nama, email, wa, segmen, tag</b>. Judul kolom boleh dihilangkan.',
    tplXlsx: { nama: 'templat_kontak.xlsx', lembar: [{ nama: 'Kontak', kolom: ['nama', 'email', 'wa', 'segmen', 'tag'], teks: [2], lebar: [26, 28, 16, 16, 16], baris: [['Bu Ayu', 'ayu@contoh.id', '081234567890', 'Mitra', 'undangan'], ['Pak Wayan', '', '081234500010', 'Komite', '']] }, { nama: 'Petunjuk', kolom: [], lebar: [100], baris: [['Isi mulai baris 2. Wajib: nama, dan minimal salah satu dari email atau wa. segmen dan tag opsional.']] }] }, tplCsv: { nama: 'templat_kontak.csv', kolom: ['nama', 'email', 'wa', 'segmen', 'tag'], baris: [['Bu Ayu', 'ayu@contoh.id', '081234567890', 'Mitra', 'undangan']] },
    pemeta: rowsKontak, kolom: [['nama', 'Nama'], ['email', 'Email'], ['wa', 'WhatsApp'], ['segmen', 'Segmen'], ['tag', 'Tag']],
    kirim: async rows => (await Api.call('crm.import', { rows })).data, selesai: () => { muatC(); kpi(); }
  });
  kpi(); muatC();
};

// ============================================================ PENGATURAN & AUDIT
Pages.pengaturan = async v => {
  const n = S.nav, admin = S.me.role === 'admin', tabs = admin ? [['umum', 'Umum'], ['keamanan', 'Keamanan'], ['audit', 'Audit Log'], ['migrasi', 'Migrasi Data']] : [['audit', 'Audit Log']];
  let tab = tabs[0][0];
  v.innerHTML = ph('W-14', 'Settings & Audit', admin ? 'Pengaturan sekolah, keamanan akses, jejak audit, dan migrasi data dari aplikasi lama.' : 'Jejak audit seluruh aktivitas penting (hanya baca).') + `<div id="pt"></div><div id="pb">${muat()}</div>`;
  const kes = {
    async umum(b) {
      const s = await Api.d('pengaturan.get', {}); if (!vivo(n)) return;
      b.innerHTML = `<div class="card" style="max-width:720px"><div class="cb">${fld('Nama sekolah', `<input class="in" name="NAMA_SEKOLAH" value="${esc(s.NAMA_SEKOLAH)}">`)}<div class="f2">${fld('Tahun ajaran', `<input class="in" name="TAHUN_AJARAN" value="${esc(s.TAHUN_AJARAN)}" placeholder="2024/2025">`)}${fld('Semester', `<select class="in" name="SEMESTER">${opsi(['GANJIL', 'GENAP'], s.SEMESTER)}</select>`)}</div><div class="f2">${fld('Jam masuk', `<input class="in" name="JAM_MASUK" value="${esc(s.JAM_MASUK)}" placeholder="07:00">`)}${fld('Toleransi terlambat (menit)', `<input class="in" name="TOLERANSI_MENIT" value="${esc(s.TOLERANSI_MENIT)}">`)}</div><div class="f2">${fld('Target kehadiran (%)', `<input class="in" name="TARGET_HADIR" value="${esc(s.TARGET_HADIR)}">`)}${fld('Batas unggah bukti (jam)', `<input class="in" name="BATAS_BUKTI_JAM" value="${esc(s.BATAS_BUKTI_JAM)}">`)}</div>${fld('Presensi mandiri siswa', `<select class="in" name="PRESENSI_MANDIRI">${opsi(['TIDAK', 'YA'], s.PRESENSI_MANDIRI)}</select>`, 'YA = siswa boleh mencatat kehadirannya sendiri (tetap diverifikasi wali kelas).')}<button class="btn" id="usave">${ic('download', 14)} Simpan pengaturan</button></div></div>`;
      $('#usave', b).onclick = e => aman(e.currentTarget, async () => { const d = {}; $$('[name]', b).forEach(i => d[i.name] = i.value); const r = await Api.call('pengaturan.simpan', d); toast(r.message); const m = await Api.d('auth.me', {}); S.cfg = m.cfg; renderShell(); });
    },
    async keamanan(b) {
      const r = await Api.d('rahasia.status', {}); if (!vivo(n)) return;
      b.innerHTML = `<div class="grid g2" style="align-items:start"><div class="card"><div class="ch"><h3>Login Google</h3>${bd(r.googleClientId.ada ? 'AKTIF' : 'BELUM', r.googleClientId.ada ? 'k' : 'r')}</div><div class="cb">${fld('Google OAuth Client ID', `<input class="in mono" id="gcid" placeholder="${esc(r.googleClientId.samar || 'xxxx.apps.googleusercontent.com')}">`, 'Dibuat di Google Cloud Console → Credentials. Origin: URL GitHub Pages Anda. Bukan rahasia, tetapi disimpan di server agar bisa diganti tanpa deploy ulang.')}<button class="btn" id="gsave">Simpan Client ID</button></div></div>
      <div class="card"><div class="ch"><h3>Akses darurat</h3>${bd(r.daruratAda ? 'AKTIF' : 'BELUM', 'm')}</div><div class="cb"><p class="sm sub" style="margin-top:0">Gunakan hanya bila login Google bermasalah. Halaman: <code class="mono">#/darurat</code>. Putar kredensial setelah login pertama.</p>${fld('Nama pengguna baru', `<input class="in" id="dun" value="${esc(r.daruratUser)}">`)}${fld('Kata sandi baru (≥12 karakter, huruf + angka)', '<input class="in" type="password" id="dpw" autocomplete="new-password">')}<button class="btn" id="dsave">Perbarui kredensial darurat</button></div></div>
      <div class="card"><div class="ch"><h3>Sesi</h3></div><div class="cb"><p class="sm sub" style="margin-top:0">Keluarkan akun Anda dari semua perangkat.</p><button class="btn o" id="ksem">${ic('out', 14)} Keluar dari semua perangkat</button></div></div></div>`;
      $('#gsave', b).onclick = e => aman(e.currentTarget, async () => { const x = await Api.call('rahasia.simpan', { kunci: 'GOOGLE_CLIENT_ID', nilai: $('#gcid', b).value }); toast(x.message); kes.keamanan(b); });
      $('#dsave', b).onclick = e => aman(e.currentTarget, async () => { const x = await Api.call('darurat.rotasi', { username: $('#dun', b).value, password: $('#dpw', b).value }); toast(x.message); $('#dpw', b).value = ''; });
      $('#ksem', b).onclick = e => aman(e.currentTarget, async () => { await Api.call('auth.keluarSemua', {}); logout(); });
    },
    async audit(b) {
      const F = { q: '', aksi: '' }, muatA = async () => {
        const d = await Api.d('audit.list', F); if (!vivo(n)) return;
        $('#abody', b).innerHTML = d.length ? d.map(x => `<tr><td class="mono sm">${wkt(x.Waktu)}</td><td class="sm">${esc(x.Pengguna)}</td><td class="mono sm b">${esc(x.Aksi)}</td><td class="mono sm">${esc(x.Tabel)}</td><td class="mono sm">${esc(x.RefID)}</td><td class="sm">${esc(x.Detail)}</td></tr>`).join('') : `<tr><td colspan="6">${kosong('list', 'Belum ada catatan.')}</td></tr>`;
        $('#aexp', b).onclick = () => unduhCsv('audit_' + hariIni() + '.csv', ['Waktu', 'Pengguna', 'Aksi', 'Tabel', 'RefID', 'Detail'], d.map(x => [x.Waktu, x.Pengguna, x.Aksi, x.Tabel, x.RefID, x.Detail]));
      };
      b.innerHTML = `<div class="card"><div class="cb row sb2"><div class="row"><input class="in" id="aq" placeholder="Cari pengguna / aksi / ID…" style="width:280px" aria-label="Cari log"><input class="in" id="aa" placeholder="Awalan aksi (mis. kas.)" style="width:200px" aria-label="Filter aksi"></div><button class="btn o" id="aexp">${ic('download', 14)} Ekspor CSV</button></div></div><div class="card mt"><div class="ch"><span class="lbl">[DATA-GRID: AUDIT LOG · 300 TERBARU]</span></div><div class="tw"><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Tabel</th><th>Ref</th><th>Detail</th></tr></thead><tbody id="abody"><tr><td colspan="6">${muat()}</td></tr></tbody></table></div><div class="cf">Log bersifat tambah-saja (append-only). Token, sandi, dan berkas tidak pernah dicatat.</div></div>`;
      $('#aq', b).oninput = debounce(e => { F.q = e.target.value; muatA(); }); $('#aa', b).oninput = debounce(e => { F.aksi = e.target.value; muatA(); }); await muatA();
    },
    async migrasi(b) {
      const TB = ['Pengguna', 'Kas_Kelas', 'Presensi', 'Temuan_Barang', 'Kegiatan_Kelas', 'Inventaris_Kelas', 'Laporan_Integritas'];
      b.innerHTML = `<div class="grid g2" style="align-items:start"><div class="card"><div class="ch"><h3>Impor dari spreadsheet aplikasi lama</h3></div><div class="cb"><p class="sm sub" style="margin-top:0">Spreadsheet lama hanya <b>dibaca</b>, tidak pernah diubah. Gunakan akun Google yang sama. Aman diulang: data tidak akan dobel.</p>${fld('URL atau ID spreadsheet lama', '<input class="in" id="msrc" placeholder="https://docs.google.com/spreadsheets/d/…">')}<div class="lbl">Tabel yang diimpor</div>${TB.map(t => `<label class="chk"><input type="checkbox" class="mt2c" value="${t}" checked><span class="mono sm">${t}</span></label>`).join('')}<label class="chk"><input type="checkbox" id="mow"><span>Timpa data yang sudah ada (nama, kelas, nilai, kondisi). Bawaan: mati.</span></label><div class="row"><button class="btn o" id="mscan">${ic('search', 14)} Pindai (dry-run)</button><button class="btn" id="mrun">${ic('upload', 14)} Jalankan impor</button></div></div></div><div class="card"><div class="ch"><h3>Hasil</h3></div><div class="cb" id="mres"><span class="sub sm">Tekan Pindai untuk melihat jumlah yang akan ditambah tanpa menulis apa pun.</span></div></div></div>`;
      const jalan = (dry, btn) => aman(btn, async () => { const d = { sumber: $('#msrc', b).value, tabel: $$('.mt2c', b).filter(c => c.checked).map(c => c.value), timpa: $('#mow', b).checked }; const r = await Api.call(dry ? 'migrasi.pindai' : 'migrasi.jalankan', d); const x = r.data;
        $('#mres', b).innerHTML = `<div class="mono sm mb">${dry ? bd('DRY-RUN', 'g') : bd('SELESAI', 'k')} Sumber: ${esc(x.sumber.nama)}</div><div class="tw"><table><thead><tr><th>Data</th><th class="num">Di lama</th><th class="num">Ditambah</th><th class="num">Diperbarui</th><th class="num">Dilewati</th></tr></thead><tbody>${Object.keys(x.laporan).map(k => `<tr><td>${esc(k)}</td><td class="num">${x.laporan[k].sumber < 0 ? '–' : x.laporan[k].sumber}</td><td class="num b">${x.laporan[k].inserted}</td><td class="num">${x.laporan[k].updated}</td><td class="num">${x.laporan[k].skipped}</td></tr>`).join('')}</tbody></table></div>${x.peringatan.length ? `<div class="chk mt" style="cursor:default">${ic('alert')}<span class="sm">${x.peringatan.map(esc).join('<br>')}</span></div>` : ''}<p class="sm sub">Sesi lama tidak ikut dipindah; pengguna cukup masuk ulang. Jalankan impor sekali lagi tepat sebelum beralih (delta sync).</p>`; toast(r.message); });
      $('#mscan', b).onclick = e => jalan(true, e.currentTarget);
      $('#mrun', b).onclick = async e => { if (await tanya('Jalankan impor sungguhan ke database aplikasi ini? Disarankan Pindai (dry-run) dahulu.', 'Jalankan impor')) jalan(false, e.currentTarget); };
    }
  };
  const tampil = async () => { $('#pt', v).innerHTML = tabBar(tabs, tab); pasangTab($('#pt', v), t => { tab = t; tampil(); }); const b = $('#pb', v); b.innerHTML = muat(); try { await kes[tab](b); } catch (e) { b.innerHTML = `<div class="card">${kosong('alert', e.message)}</div>`; } };
  tampil();
};
